from cloud_common import *  # noqa: F401,F403
R = 'f7-cloud'
T = []

# ---------------------------------------------------------------- 583 serverless
T.append(topic(583, 'serverless-functions', R, 13, 'Serverless Functions: Cold Starts, Concurrency and Cost',
 ['Explain how a function platform creates, reuses and scales execution environments',
  'Estimate concurrency as request rate × duration and protect downstream systems',
  'Decide when per-request pricing beats an always-on service'],
 2, 12, [321, 328],
 [text(583, 1, 'What the platform does for you',
   'You upload a function and a trigger: an HTTP route, a queue, a file upload. The platform creates execution environments on demand, runs your handler, reuses warm environments for later events, and removes idle ones, scaling to zero when nothing happens. Some platforms run one request per environment at a time; others let one instance handle several. You pay per request and per unit of compute time, not for idle servers.',
   ['serverless-model']),
  diagram(583, 2, 'A cold start, then warm reuse', 'Only the first request into a new environment pays for setting it up.', ['cold-start'],
   ['An event arrives and no idle environment is free',
    'The platform creates one: fetches the code and starts the runtime',
    'Initialisation code outside the handler runs: config, clients, connections',
    'The handler runs for this event',
    'The environment stays warm for a while; the next event skips straight to the handler']),
  text(583, 3, 'Worked example: concurrency is rate × duration',
   'At 500 requests per second and 200 ms per request, about 500 × 0.2 = 100 environments are busy at once. If a downstream API slows to 2 s, the same traffic needs 1,000. Accounts have a concurrency limit per region, by default 1,000 on AWS Lambda, so one slow dependency can use up the whole account and throttle unrelated functions.',
   ['function-concurrency']),
  text(583, 4, 'Pay per use is cheapest when use is uneven',
   'Per-request pricing wins for spiky or low traffic: a webhook that fires a few thousand times a day costs almost nothing and needs no capacity planning. For high, steady load the per-unit price is higher than a reserved container or VM kept busy all day, so the bill can cross over. Compare with measured traffic and include the operations work each option saves.',
   ['serverless-cost']),
  text(583, 5, 'Trap: a thousand functions, one database',
   'Each environment opens its own database connections. A spike that scales a function to 900 environments can open 900 or more connections to a database that allows 200, and the database falls over before the function does. Cap the function’s concurrency, put a connection pooler or proxy in front of the database, or move the writes onto a queue.',
   ['function-concurrency'])],
 [est('t583-a1', 'function-concurrency', 'A function receives 800 requests per second and each takes 250 ms. About how many environments are busy at once?', 'environments', 200,
   ['One request per environment at a time', 'Steady traffic'], '800 × 0.25', '800 × 0.25 s = 200 concurrent environments',
   'Sanity check: if latency doubles to 500 ms, concurrency doubles to 400 with no extra traffic, which is how slow dependencies hit concurrency limits.', 0.1, [800, 3200]),
  mc('t583-a2', 'cold-start', 'Where should a function create its database client?',
   [('a', 'Inside the handler, so each event gets a fresh client'),
    ('b', 'In initialisation code outside the handler, so warm events reuse it'),
    ('c', 'In a second function that the handler calls before each query'),
    ('d', 'In the caller, which passes the open client along with each event')], 'b',
   'Initialisation code runs once per environment and is reused by every warm event. Creating the client per event repeats the setup cost, a second function adds a network hop and its own cold starts, and open connections cannot be passed inside an event.'),
  mc('t583-a3', 'cold-start', 'A checkout endpoint must not show cold-start delays at the morning peak. Which change helps most?',
   [('a', 'Raising the function timeout from 30 seconds to 15 minutes'),
    ('b', 'Splitting the function into several smaller ones that call each other'),
    ('c', 'Logging less inside the handler so each event finishes sooner'),
    ('d', 'Keeping a pool of pre-initialised environments ready before the peak')], 'd',
   'Provisioned or minimum instances are created ahead of time, so requests land on warm environments. A longer timeout does not affect start-up, chaining functions adds more cold starts, and less logging only trims handler time.'),
  mc('t583-a4', 'function-concurrency', 'A function’s database allows 200 connections. A traffic spike scales the function to 900 environments and the database starts refusing connections. What is the best first fix?',
   [('a', 'Cap the function’s concurrency and send connections through a pooler'),
    ('b', 'Give each environment more memory so that it finishes faster'),
    ('c', 'Retry failed connections straight away in a tight loop'),
    ('d', 'Raise the timeout so requests wait longer for a connection')], 'a',
   'The fix is to bound how many connections the function can open. More memory helps a little but does not bound concurrency, tight retries add load, and longer waits keep environments busy and raise concurrency further.'),
  mc('t583-a5', 'serverless-cost', 'When does a function usually cost more than an always-on container doing the same work?',
   [('a', 'When traffic is low and arrives in rare bursts'),
    ('b', 'When the service is only used during office hours'),
    ('c', 'When load is high and steady around the clock'),
    ('d', 'When each request finishes in well under a second')], 'c',
   'Per-unit serverless compute is priced above a busy reserved instance, so high steady load is where the crossover happens. Bursty traffic, office-hours use and short requests all favour paying per use.'),
  order('t583-a6', 'cold-start', 'Order what happens on a cold invocation.',
   ['Create an environment and start the runtime', 'Run initialisation code outside the handler', 'Run the handler for the event', 'Keep the environment warm for reuse'],
   ['s2', 's4', 's1', 's3'], 'Environment, init, handler, then reuse; warm events skip the first two steps.')],
 flash(583, [('Concurrency for a function?', 'Requests per second × seconds per request.'),
             ('What is a cold start?', 'Creating an environment and running init code before the first event in it.'),
             ('Function + database at scale?', 'Cap concurrency and use a pooler or proxy, or the database runs out of connections.')]),
 src([('AWS Lambda: Understanding concurrency', 'https://docs.aws.amazon.com/lambda/latest/dg/lambda-concurrency.html'),
      ('AWS Lambda: Execution environment lifecycle', 'https://docs.aws.amazon.com/lambda/latest/dg/lambda-runtime-environment.html'),
      ('Microsoft Learn: Event-driven scaling in Azure Functions', 'https://learn.microsoft.com/en-us/azure/azure-functions/event-driven-scaling'),
      ('Google Cloud Run: Instance autoscaling', 'https://cloud.google.com/run/docs/about-instance-autoscaling')]),
 deep(['serverless-model', 'cold-start', 'function-concurrency', 'serverless-cost'], 'How function platforms run and scale your code',
  ['A function platform keeps a fleet of isolated execution environments, often lightweight virtual machines, that it can start in a fraction of a second. When an event arrives and no warm environment is free, the platform creates one, downloads the code package or image, starts the language runtime and runs your initialisation code. That whole setup is the cold start, and its length depends on the package size, the runtime and what the init code does.',
   'After the handler returns, the environment is frozen but kept for a while. The next event can reuse it and skip all setup, so anything created in initialisation, such as configuration, SDK clients and database connections, is reused across events. Environments are recycled without notice, so nothing important may live only in local memory or on local disk.',
   'Scaling follows concurrency, the number of events in flight. By Little’s law it is the arrival rate times the duration: 500 requests per second at 200 ms needs about 100 environments. Platforms that run one event per environment scale environments with that number; platforms that allow several requests per instance need fewer instances but share memory and CPU between them. Regional account limits and per-function caps bound the total, and requests beyond them are throttled.',
   'Because scaling is fast and wide, the risk moves downstream. A function can scale from ten to a thousand environments in a minute while the database it calls was sized for a hundred connections. Reserved or maximum concurrency per function, a connection pooler, and queues between functions and fragile systems keep a spike from turning into an outage somewhere else.',
   'Billing is per request plus compute time, usually measured as memory allocated times duration. That makes idle time free and spiky workloads cheap, but busy steady services can pay more than they would on a container kept 70% busy. Time limits per invocation, up to 15 minutes on AWS Lambda, and the lack of long-lived local state also rule out some workloads such as long video encodes or large in-memory caches.'],
  ['Event handlers, webhooks, file processing and APIs with spiky or low traffic.', 'Glue between managed services where running servers would mostly sit idle.'],
  ['Avoid for high, steady load where a busy container is cheaper.', 'Avoid for long-running jobs or anything needing large in-memory state between requests.'],
  ['Option', 'Scaling', 'Cost shape'],
  [['Functions', 'Per event, to zero, in seconds', 'Per request and duration; idle is free'],
   ['Containers with autoscaling', 'Per instance, in tens of seconds', 'Per instance-hour; some idle cost'],
   ['Reserved VMs', 'Manual or slow', 'Lowest per unit when kept busy']],
  'Concurrency and connections during a spike',
  ['Normal: 300 requests/s at 150 ms', 'Spike: 1,200 requests/s while a dependency slows to 600 ms', 'Each environment holds one database connection'],
  ['Normal concurrency: 300 × 0.15 = 45 environments, 45 connections.',
   'Spike concurrency: 1,200 × 0.6 = 720 environments, 720 connections.',
   'Traffic grew 4×, but concurrency grew 720 ÷ 45 = 16× because latency also grew 4×.'],
  'Concurrency multiplies rate and latency, so cap it and pool connections before the spike, not after.',
  'Published platform behaviour', 'Official documentation',
  'The AWS Lambda documentation explains concurrency as the number of in-flight requests, gives the rate × duration formula, and describes a default regional account limit and reserved concurrency for individual functions. Its execution environment page describes the init, invoke and shutdown phases and environment reuse. Azure Functions and Cloud Run document how their own instances scale and how many requests one instance can serve.',
  [('“Serverless scales without limit, so capacity is not my problem.”', '“The function scales, but its database and the account limit do not, so I’d cap concurrency and pool connections.”'),
   ('“Cold starts make serverless unusable for APIs.”', '“They only hit new environments; for a latency-critical route I’d keep a few pre-initialised instances and keep init code light.”')],
  ['Concurrency = request rate × duration; slow dependencies raise it.', 'Cold starts hit only new environments; reuse clients created in init code.', 'Protect downstream systems with concurrency caps, pools and queues.', 'Pay per use wins for spiky load; steady high load can be cheaper on containers.']),
 predict('The slow payment provider',
  'A function handles 400 requests per second at 100 ms each, about 40 environments. The payment provider it calls slows to 3 s per call. The account’s regional limit is 1,000 concurrent environments, shared with every other function.',
  [('a', 'Concurrency heads for about 1,200, hits the limit, and other functions start being throttled too',
    'Right: 400 × 3 s = 1,200 in flight, above the shared limit of 1,000.'),
   ('b', 'Concurrency stays near 40, because traffic has not changed',
    'Concurrency is rate × duration, so it grows with latency even at the same traffic.'),
   ('c', 'The platform raises the account limit by itself and nothing is throttled',
    'Account limits are quotas; requests beyond them are throttled until the quota is raised.')], 'a',
  'Give the function a reserved concurrency cap and a short timeout on the provider call, so one slow dependency cannot use up the whole account.'),
 see([(328, 'How always-on services scale, for comparison'), (53, 'Timeouts that stop slow dependencies inflating concurrency'), (321, 'Function images are containers underneath')])))

# ---------------------------------------------------------------- 584 cloud cost
T.append(topic(584, 'cloud-cost-pricing-spot-transfer', R, 14, 'Cloud Cost: Pricing Models, Spot Capacity and Data Transfer',
 ['Choose between on-demand, committed and spot capacity for each part of the load',
  'Design workloads that tolerate spot interruptions',
  'Find and reduce data transfer charges between zones, regions and the internet'],
 2, 12, [328, 329],
 [text(584, 1, 'Three ways to pay for the same machine',
   'On-demand capacity is billed by the second or hour with no commitment. Commitments, such as reserved instances, savings plans or committed-use discounts, trade a one- or three-year promise for a lower rate. Spot or preemptible capacity is spare capacity sold at a deep discount that the provider can take back at short notice: two minutes on AWS, about 30 seconds on Google Cloud.',
   ['pricing-models', 'spot-capacity']),
  text(584, 2, 'Worked example: commit to the floor, burst on spot',
   'Illustrative prices: on-demand 1.00 per instance-hour, committed 0.60, spot 0.30. Load holds at 20 instances all day and rises to 50 for 6 hours. All on-demand: 20 × 24 = 480 baseline instance-hours, plus 30 × 6 = 180 burst instance-hours, 660 in total, cost 660. Commit to the 20 baseline: 480 × 0.60 = 288, plus 180 on-demand = 468. Put the 30 burst instances on spot: 180 × 0.30 = 54, so 288 + 54 = 342, about 48% less than all on-demand.',
   ['pricing-models']),
  text(584, 3, 'Data transfer: the line nobody drew on the diagram',
   'Inbound traffic is usually free; traffic out to the internet, between regions and often between zones is billed per GB. Managed NAT gateways and load balancers can add a processing charge per GB too. A chatty service that calls a peer in another zone on every request pays for bytes in both directions, so routing calls to a replica in the same zone can cut a large, invisible bill without losing redundancy.',
   ['data-transfer-cost']),
  text(584, 4, 'Spot needs work that can be interrupted',
   'Spot suits stateless web workers behind a load balancer, batch jobs that checkpoint, CI runners and rendering farms. Handle the interruption notice: stop taking new work, checkpoint or hand back the current job, and exit. Spread across several instance types and zones so one pool running dry does not take everything, and keep the baseline that must stay up on on-demand or committed capacity.',
   ['spot-capacity']),
  text(584, 5, 'Trap: committing to the peak',
   'A commitment is billed whether or not you use it. Committing to the peak means paying the discounted rate for machines that sit idle most of the day, which can cost more than on-demand. Commit to the floor you are confident will run for the whole term, measure the usage, and add commitments in steps as the floor rises.',
   ['pricing-models'])],
 [mc('t584-a1', 'pricing-models', 'Load stays at 40 instances all day and rises to 100 for a few hours each afternoon. What should a one-year commitment cover?',
   [('a', '100 instances, so the afternoon peak also runs at the discount'),
    ('b', 'About 40 instances, the level that runs around the clock'),
    ('c', '70 instances, halfway between the floor and the peak'),
    ('d', 'None, because commitments cost more than on-demand over a year')], 'b',
   'Commit to the floor that runs all day. Committing to 100 or 70 pays for idle capacity most hours, and a commitment that is fully used is cheaper than on-demand, not more expensive.'),
  mc('t584-a2', 'spot-capacity', 'Which workload suits spot capacity best?',
   [('a', 'The only primary database, storing data on local instance disks'),
    ('b', 'A stateful game server holding players in hour-long sessions'),
    ('c', 'A licensing server that clients reach at one fixed address'),
    ('d', 'A video-transcoding queue whose jobs checkpoint as they go')], 'd',
   'Checkpointed queue work can resume elsewhere after an interruption. Losing a single primary database, ending live game sessions, or moving a fixed-address server all hurt users when the instance is reclaimed.'),
  est('t584-a3', 'data-transfer-cost', 'A service sends a steady 50 MB/s to a peer in another zone. At an illustrative 0.02 per GB for cross-zone traffic, about what does that cost in a 30-day month?', 'per month', 2592,
   ['1 GB = 1,000 MB', '30 days = 2,592,000 seconds', 'Illustrative price, not a quoted list price'], '50 MB/s × 2,592,000 s ÷ 1,000 × 0.02', '129,600 GB × 0.02 ≈ 2,590 a month',
   'Sanity check: 50 MB/s is about 4.3 TB a day, roughly 86 a day. Per-GB prices look tiny until they meet a constant stream.', 0.15, [86, 259]),
  mc('t584-a4', 'data-transfer-cost', 'Every request to a service in zone A also calls a cache node in zone B. What is the cheapest fix that keeps zone redundancy?',
   [('a', 'Move all of the service’s instances into zone B'),
    ('b', 'Switch the cache to a larger instance type'),
    ('c', 'Route each instance to a cache replica in its own zone'),
    ('d', 'Move the cache into a second region for safety')], 'c',
   'Zone-local reads remove the cross-zone traffic and keep a replica in every zone. Moving everything into zone B loses zone redundancy, a larger cache does not change the traffic path, and another region makes transfer more expensive.'),
  mc('t584-a5', 'spot-capacity', 'A worker running on spot capacity receives an interruption notice. What should it do?',
   [('a', 'Keep working; the provider moves its running job to a new instance'),
    ('b', 'Start a bigger job so more work finishes before the deadline'),
    ('c', 'Stop taking jobs, checkpoint or return the current one, and exit'),
    ('d', 'Ask the provider to extend the notice by another two minutes')], 'c',
   'The notice is the only warning before the instance is reclaimed. Providers do not migrate your job or extend the notice, and starting new work raises the amount that will be lost.'),
  tradeoff('t584-a6', 'spot-capacity', 'A team runs CI builds: about 300 jobs a day, each under 20 minutes, all safe to retry.',
   ['Jobs can be retried', 'Load swings through the day', 'Cost matters more than a rare delay'],
   [('p3', 'A fleet of committed instances sized for the busiest hour', 'Committed fleet'),
    ('p1', 'Spot runners across several types, with on-demand as a fallback', 'Spot with fallback'),
    ('p2', 'On-demand runners only, started per job', 'On-demand only')], 'p1',
   [('r1', 'An interrupted job is retried and costs a few minutes'), ('r4', 'Committed capacity is cheapest even when idle at night'),
    ('r2', 'Several instance types make it unlikely all pools run dry'), ('r3', 'Spot capacity cannot be used for CI work')],
   ['r1', 'r2'], ['r3', 'r4'],
   {'r4': 'A commitment sized for the busiest hour is paid for all night while it sits idle.',
    'r3': 'Short, retryable jobs are one of the best fits for spot.'},
   'Retryable, bursty work suits spot; spreading across pools and keeping an on-demand fallback limits the damage of a reclaim.')],
 flash(584, [('What to commit to?', 'The floor of load that runs for the whole term, not the peak.'),
             ('Spot interruption notice?', 'About 2 minutes on AWS, about 30 seconds on Google Cloud: checkpoint and exit.'),
             ('Hidden network charges?', 'Internet egress, cross-region and cross-zone transfer, NAT and load balancer processing per GB.')]),
 src([('AWS EC2: Spot Instance interruptions', 'https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/spot-interruptions.html'),
      ('Google Cloud: Spot VMs', 'https://cloud.google.com/compute/docs/instances/spot'),
      ('AWS Well-Architected: Cost Optimization Pillar', 'https://docs.aws.amazon.com/wellarchitected/latest/cost-optimization-pillar/welcome.html'),
      ('Microsoft Learn: Cost Optimization in the Well-Architected Framework', 'https://learn.microsoft.com/en-us/azure/well-architected/cost-optimization/')]),
 deep(['pricing-models', 'spot-capacity', 'data-transfer-cost'], 'Where a cloud bill comes from and how to shape it',
  ['Compute is usually the largest line. On-demand pricing is the flexible default: no promise, billed per second or hour. Commitments lower the rate in exchange for paying for a fixed amount of usage for one or three years, whether or not you use it. They are the right tool for the steady floor of load, and the wrong one for peaks that last a few hours.',
   'Spot or preemptible capacity is the provider’s spare capacity at a large discount. The provider can reclaim it when it needs the capacity back, with a short notice delivered through the instance metadata or an event. Prices and availability differ per instance type and zone, so fleets that accept several types and zones are interrupted less often than fleets that insist on one.',
   'Workloads earn spot discounts by tolerating loss. Stateless web servers behind a load balancer drain on notice. Queue workers checkpoint progress so another worker resumes the job. Batch and CI jobs are retried. A sensible fleet keeps the must-run baseline on committed or on-demand capacity and puts the elastic, interruptible part on spot.',
   'Data transfer is the quiet second bill. Traffic into the cloud is usually free, but traffic to the internet, between regions and often between zones is charged per GB, and managed NAT gateways and load balancers can add processing charges. Architecture decides it: a service that reads a cache in another zone on every request, or that sends logs out through a NAT gateway, pays for every byte. Zone-aware routing, compression, private endpoints for provider services and a CDN for public downloads cut it down.',
   'Cost work needs visibility first. Tag or label resources by team and service, review a cost report each month next to usage metrics, and look for idle resources, oversized instances, unattached disks and old snapshots. Treat cost like latency: a number with an owner, a budget and alerts, reviewed before launches rather than discovered on an invoice.'],
  ['Any production account with steady baseline load and daily or weekly peaks.', 'Batch, CI and stateless fleets that can survive an instance disappearing.'],
  ['Avoid spot for single stateful nodes such as a lone database primary.', 'Avoid long commitments for a service whose size or architecture is about to change.'],
  ['Model', 'Price', 'Risk'],
  [['On-demand', 'Highest per hour', 'None beyond the price'],
   ['Commitment', 'Lower, paid even when idle', 'Paying for unused capacity'],
   ['Spot', 'Lowest', 'Reclaimed at short notice']],
  'Blending pricing models for one service',
  ['Illustrative prices: on-demand 1.00, committed 0.60, spot 0.30 per instance-hour', '20 instances all day, 50 for 6 hours'],
  ['Usage: baseline 20 × 24 = 480 instance-hours; burst 30 × 6 = 180; total 660.',
   'All on-demand: 660 × 1.00 = 660 a day.',
   'Commit to the baseline: 480 × 0.60 = 288, plus burst on-demand 180 = 468.',
   'Commit to the baseline and burst on spot: 180 × 0.30 = 54 for the burst, so 288 + 54 = 342, about 48% below 660.'],
  'Commit to the floor and put interruptible burst on spot; committing to the peak would pay for 30 idle machines 18 hours a day.',
  'Published interruption behaviour', 'Official documentation',
  'The AWS EC2 documentation says Spot Instances receive an interruption notice two minutes before they are stopped or terminated, delivered through instance metadata and events. Google Cloud’s Spot VM documentation describes preemption with a notice of about 30 seconds and recommends designing workloads to be fault-tolerant. Both providers’ cost optimisation guidance recommends matching pricing models to usage patterns.',
  [('“We’ll buy a three-year commitment for our peak to get the best discount.”', '“I’d commit only to the floor that runs all day and cover peaks with on-demand or spot.”'),
   ('“Network is free inside the cloud.”', '“Cross-zone and cross-region traffic is billed per GB, so I’d keep chatty calls inside one zone.”')],
  ['Commit to the steady floor, not to a short-lived peak.', 'Spot suits work that can checkpoint, drain or retry.', 'Spread spot over several instance types and zones.', 'Cross-zone, cross-region and internet transfer are billed per GB; design the traffic path with that in mind.']),
 predict('The bill after going multi-zone',
  'A team spreads its services over three zones. The compute bill rises by the expected 10%, but the total bill rises by 40%. Each request now crosses zones twice on average, between the service and its cache.',
  [('a', 'Cross-zone data transfer: every request now pays for bytes crossing zones',
    'Right: zone redundancy is worth keeping, but chatty calls between zones are billed per GB.'),
   ('b', 'Zone storage: each zone keeps its own copy of the disks',
    'Possible in some designs, but this one sends every request across zones.'),
   ('c', 'Load balancer hours: there is now one load balancer per zone',
    'A load balancer spans zones; its hourly charge does not jump like this.')], 'a',
  'Keep three zones, but route each instance to a cache replica in its own zone so requests stay inside one zone.'),
 see([(328, 'Autoscaling decides how much on-demand or spot capacity runs at each hour'), (329, 'Where NAT gateways and subnets add transfer charges'), (581, 'Zone redundancy is what creates cross-zone traffic in the first place')])))
